<template><div class="review-page"><div class="review-modal"><button class="close" @click="back">×</button><h1>Write a Review</h1><div class="product"><img :src="product.image"><div><b>{{product.name}}</b><small>SKU: CL-CT-200</small></div></div><Rating label="Overall Rating" v-model="overall"/><Rating label="Designer Rating" v-model="designer"/><Rating label="Contractor Rating" v-model="contractor"/><label class="field-label">Your Review</label><textarea v-model="content" placeholder="Any other information you'd like designers to know"></textarea><label class="field-label">Upload Photos</label><div class="uploads"><button>＋</button><span v-for="img in photos" :key="img"><img :src="img"></span></div><small class="hint">Upload Images (Max 5 images)</small><label class="field-label">Would you recommend this product?</label><div><label><input type="radio" value="yes" v-model="recommend"> Yes</label><label><input type="radio" value="no" v-model="recommend"> No</label></div><div class="actions"><button @click="back">Cancel</button><button class="submit" @click="submit">Submit Review</button></div></div></div></template>
<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';const router=useRouter();const overall=ref(0),designer=ref(0),contractor=ref(0),content=ref(''),recommend=ref('yes');const photos=ref<string[]>([]);const product={name:'Modern Sofa Set',image:'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=120&h=100&fit=crop'};function back(){router.back()};function submit(){router.back()}</script>
<script lang="ts">import {defineComponent,h} from 'vue';export default defineComponent({components:{Rating:defineComponent({props:{label:String,modelValue:Number},emits:['update:modelValue'],setup(p,{emit}){return()=>h('div',{class:'rating'},[h('label',p.label),h('div',Array.from({length:5},(_,i)=>h('button',{class:i<p.modelValue?'on':'',onClick:()=>emit('update:modelValue',i+1)},'★')))])}})}})</script>
<style scoped>.review-page{position:fixed;inset:0;z-index:40;background:#0005;display:flex;align-items:center;justify-content:center;font:12px Arial;color:#30343b}.review-modal{position:relative;width:360px;background:#fff;padding:20px 24px;border-radius:3px}.close{position:absolute;right:20px;top:14px;border:0;background:none;font-size:22px}.review-modal h1{text-align:center;font-size:20px;margin:0 0 18px}.product{display:flex;gap:8px;align-items:center;margin-bottom:16px}.product img{width:60px;height:60px;object-fit:cover;border-radius:3px}.product small{display:block;color:#666;margin-top:7px}.rating{margin:13px 0}.rating label,.field-label{display:block;font-weight:600;margin-bottom:7px}.rating button{border:0;background:none;color:#e7ebef;font-size:20px;padding:0 2px;cursor:pointer}.rating button.on{color:#ffb20f}.review-modal textarea{width:100%;height:64px;box-sizing:border-box;border:1px solid #dfe3e8;padding:8px;resize:none}.uploads{display:flex;gap:6px}.uploads button{width:48px;height:48px;font-size:24px;background:#fff;border:1px solid #dfe3e8}.uploads img{width:48px;height:48px;object-fit:cover}.hint{display:block;color:#aaa;margin:5px 0 16px}.review-modal input{margin-right:4px}.review-modal label+label{margin-left:14px}.actions{text-align:right;margin-top:20px}.actions button{padding:6px 14px;margin-left:7px;background:#fff;border:1px solid #555;border-radius:3px}.actions .submit{background:#333;color:#fff}</style>

